    g = [list(r) for r in g]
    h, w = len(g), len(g[0])
    res = [list(r) for r in g]
    for c in range(w):
        nz = [(r, int(v)) for r, v in enumerate([g[r][c] for r in range(h)]) if v != 0]
        pos = defaultdict(list)
        for r, v in nz: pos[v].append(r)
        order = []
        prev = None
        for r, v in sorted(nz, key=lambda t: t[0]):
            if prev is None or v != prev:
                order.append(v)
                prev = v
        if len(order) < 2:
            continue
        lastrow = {v: max(rs) for v, rs in pos.items()}
        cur = 0
        for v in order:
            for rr in range(cur, lastrow[v]+1):
                res[rr][c] = v
            cur = lastrow[v] + 1
    return res

