def f(g):
    g=[list(r) for r in g]; h,w=len(g),len(g[0])
    res=[list(r) for r in g]
    cols={c:[] for c in range(w)}
    for r in range(h):
        for c in range(w):
            if g[r][c]!=0: cols[c].append((r,g[r][c]))
    out=[]
    for c in range(w):
        cs=sorted(set(v for _,v in cols[c]))
        # intervals per color: [min row, max row]
        segs=[(min(r for r,v in cols[c] if v==v0), max(r for r,v in cols[c] if v==v0), v0) for v0 in cs]
        segs.sort()
        filled=[False]*h
        for s in segs:
            lo,hi,v=s
            if not any(filled[rr] for rr in range(lo,hi+1)):
                for rr in range(lo,hi+1): filled[rr]=True
            if not filled[lo]: pass
        # actually simpler: paint each interval
        for s in segs:
            lo,hi,v=s
            for rr in range(lo,hi+1): res[rr][c]=v
        # gaps between consecutive intervals
        for (a1,a2,va),(b1,b2,vb) in zip(segs,segs[1:]):
            gap=b1-a2-1
            if 0<=gap<=3:
                for rr in range(a2+1,b1): res[rr][c]=vb
        # topmost extension
        if len(segs)>=2 and b1-segs[0][0]<=3 and segs[0][0]==res[0][c] or False:
            pass
        top=min(s[0] for s in segs)
        if len(segs)>=2 and segs[0][1]-segs[0][0]>=0:
            if segs[1][0]-segs[0][1]-1<=3:
                for rr in range(top,segs[0][0]): res[rr][c]=segs[0][2]
    return res

