    for c in range(w):
        nz=[(r,g[r][c]) for r in range(h) if g[r][c]!=0]
        small=False
        if len(nz)>1:
            for i in range(len(nz)-1):
                if nz[i+1][0]-nz[i][0]-1<=3: small=True
