            for rr in range(nz[0][0]): res[rr][c]=nz[0][1]
        for i in range(len(nz)-1):
            r1,v1=nz[i]; r2,v2=nz[i+1]
            if v1==v2 or (r2-r1-1)<=3:
                for rr in range(r1+1,r2): res[rr][c]=v2
    return res
